INSERT INTO exercises (id, name, category, equipment, target, muscle_group, secondary_muscles, instructions_es, image_url, gif_url) VALUES
('0274', 'crunch floor', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0274-TFqbd8t.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0274-TFqbd8t.gif'),
('3016', 'curl-up', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3016-g2oKspu.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3016-g2oKspu.gif'),
('3769', 'curtsey squat', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda. Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo. Mantén el torso erguido y el peso sobre el pie delantero. Empuja con el pie delantero para regresar a la posición inicial. Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3769-gUjqdei.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3769-gUjqdei.gif'),
('2331', 'cycle cross trainer', 'cardio', 'leverage machine', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","glutes"}', 'Ajusta la altura del asiento y colócate en la bicicleta elíptica. Coloca los pies en los pedales y sujeta el manillar. Comienza a pedalear con un movimiento suave y controlado. Mantén un ritmo constante y aumenta la resistencia si lo deseas. Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2331-XSCHmiI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2331-XSCHmiI.gif'),
('0276', 'dead bug', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","lower back"}', 'Túmbate boca arriba con los brazos extendidos hacia el techo. Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas. Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo. Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento con el brazo izquierdo y la pierna derecha. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0276-iny3m5y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0276-iny3m5y.gif'),
('0277', 'decline crunch', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0277-9Ap7miY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0277-9Ap7miY.gif'),
('0279', 'decline push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable. Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0279-i5cEhka.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0279-i5cEhka.gif'),
('0282', 'decline sit-up', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","lower back"}', 'Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0282-QLL2gdc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0282-QLL2gdc.gif'),
('1274', 'deep push up', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1274-vptOQ4N.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1274-vptOQ4N.gif'),
('0283', 'diamond push-up', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices. Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos. Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0283-soIB2rj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0283-soIB2rj.gif'),
('0284', 'donkey calf raise', 'lower legs', 'body weight', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque. Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0284-u5ESqzH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0284-u5ESqzH.gif'),
('1275', 'drop push up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1275-Q497lAE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1275-Q497lAE.gif'),
('0285', 'dumbbell alternate biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado, alternando los brazos.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0285-BU15nH4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0285-BU15nH4.gif'),
('2403', 'dumbbell alternate biceps curl (with arm blaster)', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Coloca el soporte para brazos en la parte superior de tus brazos, asegurándote de que quede bien ajustado. Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna hacia el hombro mientras contraes el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo contrario. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2403-CfKsRbG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2403-CfKsRbG.gif'),
('1646', 'dumbbell alternate hammer preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos completamente extendidos. Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1646-fy7Tgy4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1646-fy7Tgy4.gif'),
('1647', 'dumbbell alternate preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba. Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente. Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps. Continúa flexionando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1647-NlfIbzq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1647-NlfIbzq.gif'),
('1648', 'dumbbell alternate seated hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos hacia abajo. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el movimiento con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1648-6em2Dxj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1648-6em2Dxj.gif'),
('0286', 'dumbbell alternate side press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros. Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro. Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0286-izMnLqz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0286-izMnLqz.gif'),
('1649', 'dumbbell alternating bicep curl with leg raised on exercise ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Coloca un balón de ejercicio detrás de ti y apoya un pie sobre él, manteniendo el equilibrio. Con los brazos completamente extendidos y los codos cerca de los costados, flexiona una mancuerna hacia el hombro mientras mantienes el brazo superior quieto. Baja la mancuerna de vuelta a la posición inicial y repite con el otro brazo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1649-Zwiw7XR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1649-Zwiw7XR.gif'),
('1650', 'dumbbell alternating seated bicep curl on exercise ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna mientras rotas el antebrazo hasta que la palma quede frente al hombro. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite la flexión con el otro brazo. Continúa alternando flexiones el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1650-J74XlNf.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1650-J74XlNf.gif'),
('2137', 'dumbbell arnold press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper chest"}', 'Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante. Rota las muñecas mientras levantas, de modo que las palmas miren hacia adelante en la parte alta del movimiento. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2137-Xy4jlWA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2137-Xy4jlWA.gif'),
('0287', 'dumbbell arnold press v. 2', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper chest"}', 'Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante. Rota las muñecas mientras levantas, de modo que las palmas terminen mirando hacia adelante en la parte alta del movimiento. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0287-eOrFCnx.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0287-eOrFCnx.gif'),
('0288', 'dumbbell around pullover', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","latissimus dorsi"}', 'Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza en un movimiento de arco. Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0288-vi8EhoE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0288-vi8EhoE.gif'),
('0289', 'dumbbell bench press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos por encima del pecho. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Haz una pausa breve, luego empuja las mancuernas de vuelta hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0289-SpYC0Kp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0289-SpYC0Kp.gif'),
('0290', 'dumbbell bench seated press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","chest"}', 'Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos. Reclínate hacia atrás y coloca las mancuernas a los lados del pecho, con las palmas hacia adelante. Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0290-3d7wHyd.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0290-3d7wHyd.gif'),
('0291', 'dumbbell bench squat', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Coloca una mancuerna en el suelo frente a un banco. Ponte de pie de espaldas al banco con los pies separados a la altura de los hombros. Flexiona las rodillas y las caderas para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta. Una vez que los glúteos toquen el banco, empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0291-mnzcrIB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0291-mnzcrIB.gif'),
('0293', 'dumbbell bent over row', 'back', 'dumbbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que los brazos cuelguen rectos hacia el suelo, con los codos ligeramente flexionados. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0293-BJ0Hz5L.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0293-BJ0Hz5L.gif'),
('1651', 'dumbbell bicep curl lunge with bowling motion', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Da un paso adelante con el pie derecho, flexionando la rodilla derecha y bajando el cuerpo a una posición de zancada. Mientras avanzas en la zancada, flexiona las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo. En la parte baja de la zancada, gira el torso hacia la derecha, como si estuvieras lanzando una bola de boliche. Invierte el movimiento, retrocediendo con el pie derecho y regresando a la posición inicial mientras bajas las mancuernas de nuevo. Repite el movimiento de zancada y flexión, esta vez girando el torso hacia la izquierda. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1651-1VpF8db.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1651-1VpF8db.gif'),
('1652', 'dumbbell bicep curl on exercise ball with leg raised', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos. Flexiona lentamente las mancuernas hacia los hombros, manteniendo los codos cerca de los costados. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Mientras realizas el curl de bíceps, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1652-2NImIAG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1652-2NImIAG.gif'),
('1653', 'dumbbell bicep curl with stork stance', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1653-uSkDMYl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1653-uSkDMYl.gif'),
('0294', 'dumbbell biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0294-NbVPDMW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0294-NbVPDMW.gif'),
('2401', 'dumbbell biceps curl (with arm blaster)', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona las pesas mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2401-nlJsbkW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2401-nlJsbkW.gif'),
('1654', 'dumbbell biceps curl reverse', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1654-nFc4FyV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1654-nFc4FyV.gif'),
('1655', 'dumbbell biceps curl squat', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Manteniendo la espalda recta y los codos cerca de los costados, exhala y flexiona las mancuernas hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1655-niXESDw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1655-niXESDw.gif'),
('1656', 'dumbbell biceps curl v sit on bosu ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1656-H1XAdpk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1656-H1XAdpk.gif'),
('1201', 'dumbbell burpee', 'cardio', 'dumbbell', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves","shoulders","triceps","core"}', 'Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano. Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti. Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta. Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo. Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla. Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros. Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos. Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1201-0JtKWum.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1201-0JtKWum.gif'),
('0295', 'dumbbell clean', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo. Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo. Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba. Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0295-7Hg55JG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0295-7Hg55JG.gif'),
('1731', 'dumbbell close grip press', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial. Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho. Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Asegúrate de usar solo los tríceps y no usar los antebrazos ni los bíceps para ayudar a levantar las mancuernas. Después de una pausa de un segundo en la posición contraída, repite el movimiento el número de repeticiones prescrito.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1731-7jGOBF3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1731-7jGOBF3.gif'),
('0296', 'dumbbell close-grip press', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial. Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho. Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0296-RxayqAZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0296-RxayqAZ.gif'),
('0297', 'dumbbell concentration curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo. Extiende completamente el brazo y sujeta la mancuerna con un agarre supino. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps. Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0297-gvsWLQw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0297-gvsWLQw.gif'),
('3635', 'dumbbell contralateral forward lunge', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, manteniendo la espalda recta y el core activado. Baja el cuerpo flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Alterna las piernas el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3635-ecl28tP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3635-ecl28tP.gif'),
('0298', 'dumbbell cross body hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona los brazos contrayendo los bíceps, llevando las mancuernas a través del cuerpo hacia el hombro opuesto. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0298-Qyk5J3p.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0298-Qyk5J3p.gif'),
('1657', 'dumbbell cross body hammer curl v. 2', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona los brazos contrayendo los bíceps, acercando las mancuernas lo más posible al hombro opuesto. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1657-HDYiZcY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1657-HDYiZcY.gif'),
('0299', 'dumbbell cuban press', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo. Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos. Gira las muñecas de modo que las palmas queden mirando hacia adelante. Baja lentamente las mancuernas a la posición inicial, girando las muñecas de vuelta a la posición inicial mientras lo haces. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0299-QfAKy1G.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0299-QfAKy1G.gif'),
('2136', 'dumbbell cuban press v. 2', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo. Manteniendo el core activado y la espalda recta, empuja las mancuernas directamente hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos. Gira las muñecas de modo que las palmas queden mirando hacia adelante. Baja las mancuernas de nuevo hasta la altura de los hombros, girando las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2136-BqgCRif.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2136-BqgCRif.gif'),
('0300', 'dumbbell deadlift', 'upper legs', 'dumbbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Sostén una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos extendidos hacia abajo. Flexiona las caderas y las rodillas, bajando las mancuernas hacia el suelo mientras mantienes la espalda recta. Empuja con los talones y extiende las caderas y las rodillas, levantando las mancuernas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0300-nUwVh7b.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0300-nUwVh7b.gif'),
('0301', 'dumbbell decline bench press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano y extiende los brazos rectos hacia arriba por encima del pecho, con las palmas hacia adelante. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0301-DwhEmmE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0301-DwhEmmE.gif'),
('0302', 'dumbbell decline fly', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0302-xXm4nYq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0302-xXm4nYq.gif'),
('0303', 'dumbbell decline hammer press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas a los lados del pecho, manteniendo los codos ligeramente flexionados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0303-1qrWgZ2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0303-1qrWgZ2.gif'),
('1276', 'dumbbell decline one arm fly', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Túmbate en un banco declinado con una mancuerna en una mano, apoyándola sobre el muslo. Usando el muslo para ayudar a levantar la mancuerna, álzala hasta la altura de los hombros con la palma mirando hacia el torso. Gira la muñeca de modo que la palma de la mano quede mirando hacia adelante. Mientras inhalas, baja la mancuerna lentamente hacia el lado hasta sentir un estiramiento en el pecho. Exhala y usa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1276-NL6YBwN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1276-NL6YBwN.gif'),
('1617', 'dumbbell decline one arm hammer press', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho. Extiende el brazo recto hacia arriba, manteniendo el codo ligeramente flexionado. Baja la mancuerna hacia el hombro, manteniendo el codo cerca del cuerpo. Empuja la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1617-SHUMp5H.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1617-SHUMp5H.gif'),
('0305', 'dumbbell decline shrug', 'back', 'dumbbell', 'traps', 'shoulders', '{"shoulders","rhomboids"}', 'Ajusta un banco declinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el suelo. Manteniendo los brazos rectos, levanta los hombros hacia las orejas lo más alto posible. Mantén la contracción por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0305-cwsAI4G.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0305-cwsAI4G.gif'),
('0304', 'dumbbell decline shrug v. 2', 'back', 'dumbbell', 'traps', 'shoulders', '{"shoulders","rhomboids"}', 'Ajusta un banco declinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados sobre él. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos completamente extendidos. Manteniendo los brazos rectos, levanta los hombros lo más alto posible mientras juntas los omóplatos. Mantén la contracción durante una breve pausa, luego baja las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0304-bRlbdjK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0304-bRlbdjK.gif'),
('0306', 'dumbbell decline triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate en un banco declinado con la cabeza más baja que los pies y sostén una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende completamente los brazos, manteniendo los codos cerca de la cabeza. Baja lentamente las mancuernas detrás de la cabeza, flexionando los codos. Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0306-OTgkHwR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0306-OTgkHwR.gif'),
('0307', 'dumbbell decline twist fly', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Túmbate en un banco declinado con la cabeza más baja que las caderas. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento. Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0307-reFHapa.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0307-reFHapa.gif'),
('1437', 'dumbbell finger curls', 'lower arms', 'dumbbell', 'forearms', 'wrist flexors', '{"wrist flexors","wrist extensors"}', 'Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta. Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba. Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba. Repite el número de repeticiones deseado, luego cambia a la otra mano.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1437-mtXengz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1437-mtXengz.gif'),
('0308', 'dumbbell fly', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0308-yz9nUhF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0308-yz9nUhF.gif'),
('1277', 'dumbbell fly on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí. Flexiona ligeramente los codos y baja los brazos hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y contrae los músculos del pecho mientras llevas las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1277-Lt3iWnf.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1277-Lt3iWnf.gif'),
('1732', 'dumbbell forward lunge triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mantén la espalda recta y el pecho elevado. Extiende los brazos rectos por encima de la cabeza, manteniendo los codos cerca de las orejas. Baja las mancuernas detrás de la cabeza flexionando los codos. Haz una pausa por un momento, luego estira los brazos para volver a la posición inicial. Repite el movimiento el número de repeticiones deseado, luego cambia de pierna y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1732-XalXcvM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1732-XalXcvM.gif'),
('0310', 'dumbbell front raise', 'shoulders', 'dumbbell', 'delts', 'biceps', '{"biceps","trapezius"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0310-3eGE2JC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0310-3eGE2JC.gif'),
('0309', 'dumbbell front raise v. 2', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Mantén la espalda recta y activa el core. Levanta lentamente las mancuernas frente a ti, con los brazos rectos, hasta que queden a la altura de los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0309-Rr7S3yg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0309-Rr7S3yg.gif'),
('0311', 'dumbbell full can lateral raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rotator cuff"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0311-AQ0mC4Y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0311-AQ0mC4Y.gif'),
('1760', 'dumbbell goblet squat', 'upper legs', 'dumbbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna verticalmente contra el pecho con ambas manos. Manteniendo el pecho erguido y el core activado, baja el cuerpo a una posición de sentadilla empujando las caderas hacia atrás y flexionando las rodillas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1760-yn8yg1r.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1760-yn8yg1r.gif'),
('0313', 'dumbbell hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0313-slDvUAU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0313-slDvUAU.gif'),
('1659', 'dumbbell hammer curl on exercise ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1659-fY68AyX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1659-fY68AyX.gif'),
('0312', 'dumbbell hammer curl v. 2', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0312-2NpxjC1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0312-2NpxjC1.gif'),
('2402', 'dumbbell hammer curls (with arm blaster)', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso. Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante. Esta será tu posición inicial. Ahora, manteniendo el brazo superior quieto, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones recomendado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2402-GNhAeJ0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2402-GNhAeJ0.gif'),
('1664', 'dumbbell high curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante. Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1664-qAmNMJY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1664-qAmNMJY.gif'),
('3545', 'dumbbell incline alternate press', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante. Empuja las mancuernas hacia arriba con el pecho y los hombros, extendiendo completamente los brazos. Baja las mancuernas de nuevo hasta la posición inicial, manteniendo los codos ligeramente flexionados. Repite el número de repeticiones deseado, alternando los brazos.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3545-TVdivgY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3545-TVdivgY.gif'),
('0314', 'dumbbell incline bench press', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con los pies apoyados en el suelo y la espalda firmemente apoyada contra el banco. Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas hasta la altura de los hombros. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0314-ns0SIbU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0314-ns0SIbU.gif'),
('0315', 'dumbbell incline biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0315-F3xgbjF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0315-F3xgbjF.gif'),
('0316', 'dumbbell incline breeding', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sostén una mancuerna en cada mano con agarre prono, con las palmas hacia adelante. Comienza con los brazos completamente extendidos, perpendiculares al suelo. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0316-B3Rxp6L.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0316-B3Rxp6L.gif'),
('0318', 'dumbbell incline curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adelante. Apoya los brazos superiores en el banco inclinado y deja que los codos cuelguen hacia abajo, extendiendo completamente los brazos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0318-ae9UoXQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0318-ae9UoXQ.gif'),
('0317', 'dumbbell incline curl v. 2', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0317-RaflbWD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0317-RaflbWD.gif'),
('0319', 'dumbbell incline fly', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Ajusta un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0319-ESOd5Pl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0319-ESOd5Pl.gif'),
('1278', 'dumbbell incline fly on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado. Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1278-HYe1ZqR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1278-HYe1ZqR.gif'),
('0320', 'dumbbell incline hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos. Mantén la espalda contra el banco y los pies apoyados en el suelo. Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0320-ByX0WxV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0320-ByX0WxV.gif'),
('0321', 'dumbbell incline hammer press', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y coloca las mancuernas a la altura de los hombros con las palmas enfrentadas entre sí. Empuja las mancuernas hacia arriba y alejándolas del cuerpo hasta que los brazos queden completamente extendidos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0321-PG1kcIb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0321-PG1kcIb.gif'),
('1618', 'dumbbell incline hammer press on exercise ball', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Camina con los pies hacia adelante y baja el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados. Empuja las mancuernas hacia arriba y ligeramente hacia adentro, manteniendo las palmas enfrentadas entre sí. Extiende completamente los brazos, contrayendo los tríceps en la parte superior del movimiento. Baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1618-wkgnGfb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1618-wkgnGfb.gif'),
('0322', 'dumbbell incline inner biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Apoya los brazos superiores en el banco, permitiendo que los codos cuelguen hacia abajo y las palmas miren hacia adelante. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0322-LCtQPn8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0322-LCtQPn8.gif'),
('1279', 'dumbbell incline one arm fly', 'chest', 'dumbbell', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Ajusta el banco inclinado a un ángulo de 30-45 grados. Siéntate en el banco con una mancuerna en una mano, apoyándola sobre el muslo. Recuéstate en el banco, manteniendo los pies apoyados en el suelo. Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho. Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo. Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1279-Gw2HFvW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1279-Gw2HFvW.gif'),
('1280', 'dumbbell incline one arm fly on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento cuando el brazo esté paralelo al suelo. Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1280-LLNh6q5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1280-LLNh6q5.gif'),
('1619', 'dumbbell incline one arm hammer press', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","chest"}', 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo. Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros. Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo. Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1619-LL1UiTX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1619-LL1UiTX.gif'),
('1620', 'dumbbell incline one arm hammer press on exercise ball', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","chest"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados. Empuja la mancuerna hacia el techo, estirando el brazo. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1620-jDnrkar.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1620-jDnrkar.gif'),
('0323', 'dumbbell incline one arm lateral raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","triceps"}', 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyándola sobre el muslo. Inclínate hacia adelante y coloca el brazo superior contra la parte interna del muslo. Levanta la mancuerna hacia el lado, manteniendo el brazo ligeramente flexionado y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0323-aTNKZiC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0323-aTNKZiC.gif'),
('1281', 'dumbbell incline one arm press', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo. Recuéstate en el banco y coloca la mancuerna a la altura del hombro, con la palma hacia adelante. Empuja la mancuerna hacia arriba y ligeramente hacia adentro, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1281-rDAiRf9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1281-rDAiRf9.gif'),
('1282', 'dumbbell incline one arm press on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo. Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén la mancuerna a la altura del hombro con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1282-Bg5JKSH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1282-Bg5JKSH.gif'),
('0324', 'dumbbell incline palm-in press', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Planta los pies firmemente en el suelo y mantén la espalda recta contra el banco. Comienza con las mancuernas a la altura de los hombros, con los codos flexionados y las palmas enfrentadas entre sí. Empuja las mancuernas hacia arriba y alejándolas del cuerpo, extendiendo completamente los brazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0324-OVLmUuL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0324-OVLmUuL.gif'),
('1283', 'dumbbell incline press on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas hacia adelante. Camina lentamente con los pies hacia adelante, bajando el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados. Empuja las mancuernas hacia arriba, extendiendo completamente los brazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1283-bfiHMpI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1283-bfiHMpI.gif'),
('0325', 'dumbbell incline raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","triceps"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate en el banco y levanta las mancuernas hasta la altura de los hombros, con las palmas hacia adelante. Manteniendo la espalda contra el banco, exhala y levanta las mancuernas por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0325-nxW6BkN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0325-nxW6BkN.gif'),
('0326', 'dumbbell incline rear lateral raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano. Extiende los brazos rectos hacia abajo con las palmas enfrentadas entre sí. Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0326-vYk8lqw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0326-vYk8lqw.gif'),
('0327', 'dumbbell incline row', 'back', 'dumbbell', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Toma una mancuerna en cada mano y siéntate en el banco con el pecho apoyado contra la inclinación. Extiende completamente los brazos, dejando que las mancuernas cuelguen rectas hacia abajo desde los hombros. Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0327-7vG5o25.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0327-7vG5o25.gif'),
('0328', 'dumbbell incline shoulder raise', 'chest', 'dumbbell', 'serratus anterior', 'deltoids', '{"deltoids","trapezius"}', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo. Apoya las mancuernas sobre los muslos y recuéstate en el banco. Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante. Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0328-6e2DcYX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0328-6e2DcYX.gif'),
('0329', 'dumbbell incline shrug', 'back', 'dumbbell', 'traps', 'shoulders', '{"shoulders"}', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano. Coloca los pies planos sobre el suelo y deja que los brazos cuelguen rectos hacia abajo con las palmas hacia el cuerpo. Manteniendo los brazos rectos, encoge los hombros hacia las orejas lo más alto posible. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0329-JymLInS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0329-JymLInS.gif'),
('3542', 'dumbbell incline t-raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate hacia adelante y deja que los brazos cuelguen rectos hacia abajo, perpendiculares al suelo. Manteniendo los brazos rectos, levántalos hacia los lados hasta que queden paralelos al suelo, formando una ''T'' con el cuerpo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3542-jgbvVJ0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3542-jgbvVJ0.gif'),
('0330', 'dumbbell incline triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adentro. Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza. Baja las mancuernas detrás de la cabeza flexionando los codos, manteniendo los brazos superiores quietos. Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0330-OVIKwsd.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0330-OVIKwsd.gif'),
('0331', 'dumbbell incline twisted flyes', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho, con los brazos extendidos. Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento. Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0331-1PLE8e9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0331-1PLE8e9.gif'),
('1733', 'dumbbell incline two arm extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos. Recuéstate lentamente en el banco, manteniendo las mancuernas cerca del pecho. Una vez completamente recostado, extiende los brazos rectos hacia el techo, manteniendo los codos ligeramente flexionados. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1733-U7D9Fx3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1733-U7D9Fx3.gif'),
('3541', 'dumbbell incline y-raise', 'back', 'dumbbell', 'upper back', 'shoulders', '{"shoulders","rear deltoids"}', 'Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro. Inclínate ligeramente hacia adelante y deja que los brazos cuelguen rectos hacia abajo, manteniendo una ligera flexión en los codos. Levanta los brazos hacia los lados y hacia arriba formando una Y hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3541-PbzNu7c.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3541-PbzNu7c.gif'),
('0332', 'dumbbell iron cross', 'shoulders', 'dumbbell', 'delts', 'triceps', '{"triceps","chest"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo. Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0332-cALkHHX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0332-cALkHHX.gif'),
('0333', 'dumbbell kickback', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0333-W6PxUkg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0333-W6PxUkg.gif'),
('1734', 'dumbbell kickbacks on exercise ball', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","back"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1734-cAvTaSg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1734-cAvTaSg.gif'),
('1660', 'dumbbell kneeling bicep curl exercise ball', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Arrodíllate en el suelo con un balón de estabilidad frente a ti. Coloca los codos sobre el balón de estabilidad, sosteniendo una mancuerna en cada mano con las palmas hacia arriba. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1660-2JCuFTU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1660-2JCuFTU.gif'),
('0334', 'dumbbell lateral raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0334-DsgkuIt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0334-DsgkuIt.gif'),
('0335', 'dumbbell lateral to front raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Luego, levanta los brazos frente a ti hasta que queden paralelos al suelo, manteniendo nuevamente una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0335-xMjBKwn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0335-xMjBKwn.gif'),
('0336', 'dumbbell lunge', 'upper legs', 'dumbbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Alterna las piernas el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0336-RRWFUcw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0336-RRWFUcw.gif'),
('1658', 'dumbbell lunge with bicep curl', 'upper arms', 'dumbbell', 'biceps', 'quadriceps', '{"quadriceps","hamstrings"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. La rodilla derecha debe quedar flexionada en un ángulo de 90 grados y la rodilla izquierda debe quedar justo por encima del suelo. Mientras avanzas en la zancada, flexiona simultáneamente las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte baja de la zancada, luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas de nuevo a los costados. Repite la zancada y el curl de bíceps en el lado opuesto, dando un paso adelante con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1658-Mz6lLcW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1658-Mz6lLcW.gif'),
('0337', 'dumbbell lying extension (across face)', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí. Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo. Haz una pausa por un momento, luego contrae los tríceps para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0337-L2V5Nan.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0337-L2V5Nan.gif'),
('1729', 'dumbbell lying alternate extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido. Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial. Repite con el otro brazo, alternando lados el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1729-NfP83rA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1729-NfP83rA.gif'),
('0338', 'dumbbell lying elbow press', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho. Baja las mancuernas hacia los hombros flexionando los codos, manteniendo los brazos superiores quietos. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial extendiendo los codos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0338-eOCOwIR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0338-eOCOwIR.gif'),
('0863', 'dumbbell lying external shoulder rotation', 'shoulders', 'dumbbell', 'delts', 'rotator cuff', '{"rotator cuff","triceps"}', 'Túmbate de lado en un banco plano con el brazo superior contra el costado y el codo flexionado a 90 grados. Sostén una mancuerna en la mano con la palma hacia abajo. Manteniendo el brazo superior contra el costado, gira lentamente el antebrazo hacia arriba lo más posible. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0863-bmBf7LN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0863-bmBf7LN.gif'),
('0339', 'dumbbell lying femoral', 'upper legs', 'dumbbell', 'hamstrings', 'glutes', '{"glutes"}', 'Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo. Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0339-FkBIE6a.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0339-FkBIE6a.gif'),
('0340', 'dumbbell lying hammer press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba. Baja las mancuernas a los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0340-7gdLIXa.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0340-7gdLIXa.gif'),
('2470', 'dumbbell lying on floor rear delt raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Túmbate boca abajo en el suelo con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos frente a ti, manteniendo una ligera flexión en los codos. Activando los músculos de los hombros, levanta los brazos hacia arriba y hacia los lados, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2470-Ion0XWz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2470-Ion0XWz.gif'),
('0341', 'dumbbell lying one arm deltoid rear', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia adentro. Extiende el brazo recto hacia el suelo, manteniéndolo cerca del cuerpo. Levanta el brazo hacia arriba y hacia atrás, acercando el omóplato hacia la columna. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0341-gSw59a4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0341-gSw59a4.gif'),
('0343', 'dumbbell lying one arm press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en una mano y los pies apoyados en el suelo. Sostén la mancuerna a la altura del hombro con la palma hacia adelante. Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0343-zGSIWQi.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0343-zGSIWQi.gif'),
('0342', 'dumbbell lying one arm press v. 2', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate boca arriba en un banco con la espalda apoyada y los pies planos sobre el suelo. Sostén una mancuerna en una mano con la palma hacia los pies. Extiende el brazo recto hacia el techo, manteniendo el codo ligeramente flexionado. Baja lentamente la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0342-K3dIO25.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0342-K3dIO25.gif'),
('0344', 'dumbbell lying one arm pronated triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en una mano con la palma hacia abajo, y extiende el brazo recto por encima del hombro. Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo. Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0344-wyaqzOS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0344-wyaqzOS.gif'),
('0345', 'dumbbell lying one arm rear lateral raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el suelo. Mantén el brazo recto y levanta la mancuerna hacia el lado, alejándola del cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0345-KwFGiEP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0345-KwFGiEP.gif'),
('0346', 'dumbbell lying one arm supinated triceps extension', 'upper arms', 'dumbbell', 'triceps', 'forearms', '{"forearms"}', 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre supino, y extiende el brazo recto por encima del hombro. Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo. Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0346-zZlORz6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0346-zZlORz6.gif'),
('0347', 'dumbbell lying pronation', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","shoulders"}', 'Túmbate boca abajo en un banco con el pecho hacia abajo y los brazos extendidos rectos hacia abajo, sosteniendo una mancuerna en cada mano. Gira las palmas de modo que queden mirando hacia arriba. Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas mientras giras las palmas hacia abajo. Inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0347-mym4hJo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0347-mym4hJo.gif'),
('2705', 'dumbbell lying pronation on floor', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","triceps"}', 'Túmbate boca abajo en el suelo con los brazos extendidos rectos frente a ti, sosteniendo una mancuerna en cada mano. Gira las palmas de modo que queden mirando hacia el suelo. Manteniendo los brazos rectos, levanta las mancuernas del suelo contrayendo los antebrazos. Continúa levantando hasta que los antebrazos estén completamente contraídos y las mancuernas queden a la altura de los hombros. Mantén la posición por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2705-7RWNjiB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2705-7RWNjiB.gif'),
('1284', 'dumbbell lying pullover on exercise ball', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders","back"}', 'Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón. Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1284-iK59oEA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1284-iK59oEA.gif'),
('1328', 'dumbbell lying rear delt row', 'back', 'dumbbell', 'upper back', 'shoulders', '{"shoulders","biceps"}', 'Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas hacia adentro. Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos. Activando los músculos de la espalda, levanta las mancuernas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1328-XUUD0Fs.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1328-XUUD0Fs.gif'),
('0348', 'dumbbell lying rear lateral raise', 'shoulders', 'dumbbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos. Activando los músculos de los hombros, levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0348-53Ttlck.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0348-53Ttlck.gif'),
('1735', 'dumbbell lying single extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en una mano y el brazo completamente extendido por encima del pecho. Baja la mancuerna de manera controlada hacia la frente, manteniendo el brazo superior quieto. Haz una breve pausa en la parte inferior del movimiento, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1735-6MfS53i.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1735-6MfS53i.gif'),
('0349', 'dumbbell lying supination', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","shoulders"}', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0349-M2Pm3zj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0349-M2Pm3zj.gif'),
('2706', 'dumbbell lying supination on floor', 'lower arms', 'dumbbell', 'forearms', 'biceps', '{"biceps","shoulders"}', 'Túmbate boca arriba en el suelo con las piernas extendidas y los brazos a los costados, sosteniendo una mancuerna en cada mano. Gira las palmas hacia arriba, manteniendo los codos cerca de los costados. Flexiona lentamente las mancuernas hacia los hombros, contrayendo los antebrazos. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2706-rEhi2o5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2706-rEhi2o5.gif'),
('1661', 'dumbbell lying supine biceps curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo. Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1661-XVzF3iZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1661-XVzF3iZ.gif'),
('0350', 'dumbbell lying supine curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0350-KUaZst7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0350-KUaZst7.gif'),
('0351', 'dumbbell lying triceps extension', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo. Baja las mancuernas hacia la frente, flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0351-mpKZGWz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0351-mpKZGWz.gif'),
('1662', 'dumbbell lying wide curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1662-qm9veZw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1662-qm9veZw.gif'),
('0352', 'dumbbell neutral grip bench press', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sostén una mancuerna en cada mano con agarre neutro (palmas enfrentadas entre sí) y los brazos extendidos rectos hacia arriba sobre el pecho. Baja lentamente las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0352-pP8wP2P.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0352-pP8wP2P.gif'),
('1285', 'dumbbell one arm bench fly', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders"}', 'Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo. Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo. Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial. Sostén la mancuerna directamente sobre el hombro con el brazo extendido y la palma hacia adentro. Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo. Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento y lleva la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1285-o5Jsk92.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1285-o5Jsk92.gif'),
('0292', 'dumbbell one arm bent-over row', 'back', 'dumbbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que la mancuerna cuelgue recta hacia el suelo, con el brazo completamente extendido. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0292-C0MA9bC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0292-C0MA9bC.gif'),
('1286', 'dumbbell one arm chest fly on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo. Camina con los pies hacia adelante, haciendo rodar el balón hasta que la parte superior de la espalda quede apoyada en el balón y la cabeza, el cuello y los hombros queden fuera de él. Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento cuando el brazo esté paralelo al suelo. Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1286-Bpkf41o.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1286-Bpkf41o.gif'),
('0353', 'dumbbell one arm concentration curl (on stability ball)', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna en una mano con la palma hacia arriba y el brazo extendido hacia el suelo. Apoya el codo en la parte interna del muslo, justo por encima de la rodilla. Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa por un momento en la parte superior del movimiento, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0353-k5IpyHg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0353-k5IpyHg.gif'),
('1287', 'dumbbell one arm decline chest press', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho. Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco. Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1287-REGM1dE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1287-REGM1dE.gif'),
('1288', 'dumbbell one arm fly on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la parte superior de la espalda quede apoyada sobre el balón de estabilidad. Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro. Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo. Haz una pausa por un momento, luego contrae los músculos del pecho para llevar la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1288-Am02iPd.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1288-Am02iPd.gif'),
('1736', 'dumbbell one arm french press on exercise ball', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia arriba y el codo flexionado en un ángulo de 90 grados. Extiende el brazo recto hacia el techo, manteniendo el codo quieto. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1736-ziFKQXP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1736-ziFKQXP.gif'),
('1663', 'dumbbell one arm hammer preacher curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco scott con una mancuerna en una mano y el brazo superior apoyado sobre la almohadilla. Sostén la mancuerna con agarre neutro (palmas hacia el cuerpo). Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1663-4dF3maG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1663-4dF3maG.gif'),
('1621', 'dumbbell one arm hammer press on exercise ball', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders","chest"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados. Coloca la otra mano en la cadera para mantener el equilibrio. Empuja la mancuerna hacia arriba, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1621-VYmYxK5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1621-VYmYxK5.gif'),
('1289', 'dumbbell one arm incline chest press', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ajusta el banco inclinado a un ángulo de 45 grados. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sostén una mancuerna en una mano con agarre prono, apoyándola sobre el hombro. Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1289-PDaMuyV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1289-PDaMuyV.gif'),
('0354', 'dumbbell one arm kickback', 'upper arms', 'dumbbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados. Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0354-bQy2Eni.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0354-bQy2Eni.gif'),
('0355', 'dumbbell one arm lateral raise', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","triceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo. Mantén la espalda recta y el core activado durante todo el ejercicio. Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0355-n5cWCsI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0355-n5cWCsI.gif'),
('0356', 'dumbbell one arm lateral raise with support', 'shoulders', 'dumbbell', 'delts', 'trapezius', '{"trapezius","rotator cuff"}', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo. Coloca la otra mano sobre una superficie estable, como un banco o una pared, para apoyarte. Mantén la espalda recta y activa el core. Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo. Continúa levantando hasta que el brazo quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0356-Yg7MJAT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0356-Yg7MJAT.gif'),
('1290', 'dumbbell one arm press on exercise ball', 'chest', 'dumbbell', 'pectorals', 'shoulders', '{"shoulders","triceps","core"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna en una mano y colócala a la altura del hombro, con el codo flexionado y la palma hacia adelante. Empuja lentamente la mancuerna hacia arriba hasta que el brazo quede completamente extendido, manteniendo el core activado y el equilibrio sobre el balón de estabilidad. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1290-QZFv5ui.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1290-QZFv5ui.gif'),
('1665', 'dumbbell one arm prone curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo. Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo. Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1665-JWjujiY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1665-JWjujiY.gif'),
('1666', 'dumbbell one arm prone hammer curl', 'upper arms', 'dumbbell', 'biceps', 'forearms', '{"forearms"}', 'Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido. Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1666-LIGZSTA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1666-LIGZSTA.gif'),
('1291', 'dumbbell one arm pullover on exercise ball', 'chest', 'dumbbell', 'pectorals', 'triceps', '{"triceps","latissimus dorsi","rhomboids"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho. Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1291-bQHPBU3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1291-bQHPBU3.gif');
